function wpbp_auth_001( string $user_login, string $reset_key ): string {
    $result = check_password_reset_key( $reset_key, $user_login );

    if ( $result instanceof WP_User ) {
        return 'valid';
    }

    if ( is_wp_error( $result ) && 'expired_key' === $result->get_error_code() ) {
        return 'expired';
    }

    return 'invalid';
}

add_filter(
    'authenticate',
    static function ( $user ) {
        if ( ! $user instanceof WP_User ) {
            return $user;
        }

        if ( '1' === (string) get_user_meta( $user->ID, 'wpbp_suspended', true ) ) {
            return new WP_Error( 'wpbp_suspended', __( 'This account is suspended.' ) );
        }

        return $user;
    },
    30,
    3
);

function wpbp_auth_003( int $user_id, string $application_name ) {
    if ( WP_Application_Passwords::application_name_exists_for_user( $user_id, $application_name ) ) {
        return new WP_Error( 'wpbp_duplicate_name', __( 'An application password with that name already exists.' ) );
    }

    $created = WP_Application_Passwords::create_new_application_password( $user_id, array( 'name' => $application_name ) );

    if ( is_wp_error( $created ) ) {
        return $created;
    }

    return WP_Application_Passwords::chunk_password( $created[0] );
}

function wpbp_auth_004( int $user_id, string $token_to_keep ): int {
    $manager = WP_Session_Tokens::get_instance( $user_id );
    $before  = count( $manager->get_all() );

    $manager->destroy_others( $token_to_keep );

    return $before - count( $manager->get_all() );
}

function wpbp_auth_005( int $user_id, string $password ): string {
    $user = get_userdata( $user_id );

    if ( ! $user instanceof WP_User ) {
        return 'invalid';
    }

    if ( ! wp_check_password( $password, $user->user_pass, $user->ID ) ) {
        return 'invalid';
    }

    if ( wp_password_needs_rehash( $user->user_pass, $user->ID ) ) {
        wp_set_password( $password, $user->ID );
        return 'rehashed';
    }

    return 'current';
}

add_filter(
    'registration_errors',
    static function ( $errors, $sanitized_user_login, $user_email ) {
        $blocked = (array) get_option( 'wpbp_blocked_domains', array() );
        $domain  = strtolower( substr( strrchr( (string) $user_email, '@' ) ?: '', 1 ) );

        if ( '' !== $domain && in_array( $domain, $blocked, true ) ) {
            $errors->add( 'wpbp_blocked_domain', __( 'Registrations from that email domain are not accepted.' ) );
        }

        return $errors;
    },
    10,
    3
);

add_filter( 'wp_send_new_user_notification_to_admin', '__return_false' );

add_filter(
    'wp_new_user_notification_email',
    static function ( $email ) {
        $email['message'] = rtrim( $email['message'] ) . "\r\n\r\nSupport: wpbp-support@example.org";

        return $email;
    },
    10,
    3
);

add_filter(
    'login_redirect',
    static function ( $redirect_to, $requested_redirect_to, $user ) {
        if ( ! $user instanceof WP_User ) {
            return $redirect_to;
        }

        if ( $user->has_cap( 'manage_options' ) ) {
            return $requested_redirect_to ? $requested_redirect_to : $redirect_to;
        }

        if ( $user->has_cap( 'edit_posts' ) ) {
            return admin_url( 'edit.php' );
        }

        return home_url();
    },
    10,
    3
);

function wpbp_auth_009( int $user_id, string $token ): bool {
    $records = get_user_meta( $user_id, 'wpbp_api_tokens', true );

    if ( ! is_array( $records ) ) {
        return false;
    }

    foreach ( $records as $record ) {
        if ( empty( $record['hash'] ) || ! empty( $record['revoked'] ) ) {
            continue;
        }

        if ( wp_verify_fast_hash( $token, (string) $record['hash'] ) ) {
            return true;
        }
    }

    return false;
}
